#!/usr/bin/env python3
"""部品別の熱概算(再循環を含む簡易モデル) → docs/thermal-analysis.md。数値は公開仕様+仮定。CFD/実測で置換すること。"""
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import power_budget as PB
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
rho, cp = 1.2, 1005.0
# 発熱(W): 出典は parts.json / 公式TDP・TGP, 内訳は仮定を明記
_b = PB.budget('最大(CPU PPT+GPU TGP同時)')   # 電力収支は tools/power_budget.py が単一源(二重計上なし, 合計=AC入力)
Q = {'CPU 9950X3D (PPT 230W想定)': _b['cpu'], 'GPU RTX 5070 Ti 小型 (TGP)': _b['gpu'], '基板/VRM損失+RAM+SSD': _b['board'], 'ファン/ポンプ': _b['fans'], f"PSU損失(DC {_b['dc']:.0f}W→AC {_b['ac']:.0f}W, 効率{_b['eff']*100:.1f}%)": _b['psu_loss'], 'コントローラ+パネル': _b['panel']}
P_tot = sum(Q.values())
fans = {'ラジエーターP12 Pro×2': 131 * 2}   # m3/h 公称
flow_nom = sum(fans.values())
out = ['# 熱解析(部品別・再循環モデル) (自動生成: tools/thermal_calc.py)', '', '> **重要(R10E-001/P0・未解決)**: ラジエーター吸気分離ダクトは layout.json(rad_duct)に**寸法だけ提案(PROPOSED)**。ホース2本の通過のため y<78 は開放で分離は不完全、気密・ファン位置・熱効果は未検証。下表の『CPU(外気直吸気)=83℃』はそれを前提にした数字で、分離が無い場合(B行)は Tjmax 近傍/超過になりうる。実測またはCFDで効果を確認するまで熱の合格を宣言しない(UNVERIFIED)。', '', '**簡易モデルであり実機試験の代替ではない**。仮定: 室温25℃、ドーム内は完全混合、公称風量の実効係数を3水準で評価。CPU/GPU温度は公開レビュー値(未検証)で外挿。', '', '## 発熱内訳(W)', '| 項目 | W |', '|---|---|'] + [f'| {k} | {v} |' for k, v in Q.items()] + [f'| **合計** | **{P_tot}** |', '', '電源負荷(12V系: CPU230+GPU300+他≈100)≈630W、SF1000の使用率≈63%(余裕37%)。', '']
out += ['## ドーム内空気温度(完全混合)', 'v7の気流方針: **ラジエーターのファン(P12 Pro×2)はドーム側に置き外気をラジエーターへ直接吸気(押し込み)**。ラジエーターを通った空気(CPU熱)はドーム内(プレナム)へ入り、**正圧**で全面格子とケースファンから排出される。GPUファンはプレナム空気を吸う。CPU冷却の吸気温度は外気。評価: (A) CPU熱がプレナムに入らない下限、(B) CPU熱を含めプレナム完全混合(本構成の実態に近い)。', '', '| 実効風量係数 | 総風量 m3/h | (A) 内部温度上昇 K | (B) 内部温度上昇 K |', '|---|---|---|---|']
for k in (0.7, 0.55, 0.4):
    V = flow_nom * k / 3600; dA = (P_tot - Q['CPU 9950X3D (PPT 230W想定)']) / (rho * cp * V); dB = P_tot / (rho * cp * V)
    out.append(f'| {k} | {flow_nom*k:.0f} | {dA:.1f} | {dB:.1f} |')
out += ['', '## 部品温度の概算(係数0.55, 室温25℃)']
V = flow_nom * 0.55 / 3600; dA = (P_tot - 230) / (rho * cp * V); dB = P_tot / (rho * cp * V)
cpu_dT = 58   # 240mm AIO + 9950X3D 230W: Neowin最大83.4℃(冷却器不明)等から概算(室温比+55〜60K, 未検証)
gpu_dT = 42   # 2.5スロット2ファンGPU 180W: 室温比+35〜45K(未検証)
out += ['| 部品 | 室温+内部上昇 | 部品固有上昇(仮定) | 推定温度 | 上限 | 判定 |', '|---|---|---|---|---|---|']
for nm, dT, lim in (('CPU(v7: ラジエーターが外気を直吸気)', cpu_dT, 90), ('CPU(B: 再循環・最悪)', cpu_dT, 90), ('GPU(プレナム空気)', gpu_dT, 83)):
    ti = 25 + (0 if 'v7' in nm else dB); t = ti + dT
    out.append(f'| {nm} | {ti:.1f} | {dT} | {t:.0f}℃ | {lim}℃ | {"余裕あり" if t < lim - 5 else "要注意" if t < lim else "超過"} |')
out += ['', '## 懸念と対策', '- **9950X3D@PPT230WはTjmax(95℃)に近い**: 外気直吸気でも約83℃(推定)で余裕は小さく、再循環(最悪)なら超過する。対策: ラジエーターの外気経路を確実に分離、ファン曲線、必要なら温度連動のPPT上限(ユーザー方針は制限しないが安全装置として)、LF III Pro 240の実測(U44)。', '- 縦置きディスプレイ背面は自然対流が上向きに働くため、吸気を下側/排気を上側に偏らせると効率が上がる(v7: 均一格子+内部の仕切りで流路を作る案をCFDで評価)。', '- GPUファンはドーム側の空気を吸う → 内部温度が上がるとGPU温度が直接上がる。内部温度上昇を≤10K(B)に抑える風量を確保。', '- PSU/ポンプVRMファン/基板は局所温度を別途実測。パネル背面温度≤45℃を要確認(バックライト寿命)。', '', '## 試験計画(未実施)', '1. 熱電対(K型)8点: 吸気(格子外)、ドーム内中央、ラジエーター吸気/排気、CPU(ソフト)、GPU(ソフト)、VRM、SSD、パネル背面、外装表面。', '2. 負荷: Cinebench 30分+FurMark 30分同時。室温25±2℃。ファンRPMとSPLを同時記録。', '3. 合格: CPU<90℃, GPU<83℃, 内部上昇≤10K, パネル背面≤45℃, 外装表面≤48℃, 騒音≤38dBA。', '4. 不合格時: 格子の開口率拡大、ラジエーターを直排気にする仕切り、ケースファン増設(2基)。']
open(f'{R}/docs/thermal-analysis.md', 'w').write('\n'.join(out) + '\n'); print('\n'.join(out[8:22]))
